components.css:
.ds-selector-multiple { min-width: 0; position: relative; }
.ds-selector-multiple.abierto { z-index: 50; }
.ds-selector-label { display: block; margin-bottom: 8px; font-size: 12px; font-weight: 550; color: var(--tinta-2); }
.ds-selector-trigger { display: flex; align-items: center; gap: 8px; width: 100%; min-height: 44px; padding: 10px 12px; border: 1px solid var(--linea-fuerte); border-radius: 8px; background: var(--superficie); color: var(--tinta); font: inherit; font-size: 13px; cursor: pointer; text-align: left; }
.ds-selector-trigger > span:first-child { flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.ds-selector-trigger > svg { color: var(--tinta-2); flex-shrink: 0; transition: transform 160ms ease-out; }
.ds-selector-trigger:hover { border-color: var(--acento); background: var(--superficie-2); }
.ds-selector-trigger[aria-expanded="true"] { border-color: var(--acento); }
.ds-selector-trigger[aria-expanded="true"] > svg { transform: rotate(180deg); }
.ds-selector-count { padding: 1px 6px; border-radius: 4px; color: var(--acento); background: var(--acento-suave); font-size: 11px; font-variant-numeric: tabular-nums; }
.ds-selector-etiquetas { display: flex; flex-wrap: wrap; gap: 5px; margin-top: 8px; }
.ds-selector-etiqueta { display: inline-flex; align-items: center; gap: 4px; max-width: 100%; min-width: 0; border-radius: 5px; padding: 3px 6px 3px 8px; background: var(--acento-suave); color: var(--acento); font-size: 11px; }
.ds-selector-etiqueta > span { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.ds-selector-etiqueta button { display: grid; place-items: center; flex-shrink: 0; width: 24px; height: 24px; padding: 0; border: 0; border-radius: 4px; background: transparent; color: currentColor; cursor: pointer; }
.ds-selector-etiqueta button:hover { background: var(--acento-borde); }
.ds-selector-etiqueta svg { width: 12px; height: 12px; }
.ds-selector-resto { align-self: center; padding: 3px 5px; color: var(--tinta-2); font-size: 11px; }
.ds-selector-panel { position: fixed; display: flex; flex-direction: column; width: 340px; max-height: calc(100dvh - 128px); border-radius: 12px; background: var(--superficie); color: var(--tinta); box-shadow: var(--sombra-flotante); overflow: hidden; z-index: 50; }
.ds-selector-search { display: flex; align-items: center; gap: 9px; padding: 14px 16px; border-bottom: 1px solid var(--linea); color: var(--tinta-2); }
.ds-selector-search input { border: 0; min-width: 0; width: 100%; padding: 0; outline: none; background: transparent; color: var(--tinta); font: inherit; font-size: 13px; }
.ds-selector-search:focus-within { box-shadow: inset 0 -2px var(--acento); }
.ds-selector-search input::placeholder { color: var(--tinta-2); }
.ds-selector-acciones { display: flex; justify-content: space-between; gap: 12px; padding: 9px 16px; }
.ds-selector-options { overflow-y: auto; min-height: 0; max-height: 280px; padding: 2px 8px 8px; scrollbar-width: thin; scrollbar-color: var(--linea-fuerte) transparent; }
.ds-selector-option { display: flex; align-items: center; gap: 12px; min-height: 44px; padding: 10px 9px; border-radius: 6px; cursor: pointer; }
.ds-selector-option:hover, .ds-selector-option:focus-within { background: var(--superficie-2); }
.ds-selector-option:has(input:checked) { background: var(--acento-suave); }
.ds-selector-option input { width: 16px; height: 16px; flex-shrink: 0; margin: 0; accent-color: var(--acento); cursor: pointer; }
.ds-selector-option > span { display: grid; gap: 3px; font-size: 13px; }
.ds-selector-option small { font-size: 11px; color: var(--tinta-2); }
.ds-selector-empty { color: var(--tinta-2); font-size: 12px; padding: 12px 9px; }
.ds-selector-month { display: flex; align-items: center; justify-content: space-between; gap: 10px; padding: 10px 16px; border-top: 1px solid var(--linea); font-size: 11px; color: var(--tinta-2); }
.ds-selector-month input { min-width: 0; max-width: 170px; border: 1px solid var(--linea); padding: 6px; border-radius: 5px; font: inherit; color: var(--tinta); background: var(--superficie); }
.ds-selector-footer { display: flex; align-items: center; justify-content: space-between; gap: 12px; padding: 12px 16px; border-top: 1px solid var(--linea); }
.ds-selector-footer > span { color: var(--tinta-2); font-size: 11px; }
.ds-selector-apply { min-height: 36px; padding: 8px 15px; border: 0; border-radius: 6px; background: var(--acento); color: var(--sobre-acento); font: inherit; font-size: 12px; font-weight: 550; cursor: pointer; }
.ds-selector-apply:disabled { opacity: .5; cursor: default; }
.ds-selector-apply:hover:enabled { background: var(--acento-hover); }
.ds-selector-multiple { font-family:var(--fuente,'Geist Variable',sans-serif); max-width:340px; } .ds-selector-panel { position:relative; width:100%; margin-top:8px; } .ds-selector-acciones button { padding:3px 0; border:0; color:var(--acento); background:transparent; font:inherit; font-size:11px; cursor:pointer; } .ds-selector-acciones button:hover { text-decoration:underline; text-underline-offset:3px; } .ds-selector-multiple button:focus-visible,.ds-selector-multiple input:focus-visible { outline:2px solid var(--acento); outline-offset:3px; } .ds-selector-search input:focus-visible { outline:none; caret-color:var(--acento); } @media(prefers-reduced-motion:reduce) { .ds-selector-trigger > svg { transition:none; } }
@media(max-width:760px){.ds-selector-apply,.ds-selector-acciones button{min-height:44px;}}

.ds-territorio-indicadores { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 18px; margin: 0 0 30px; }
.ds-territorio-indicadores article { padding: 22px; min-width: 0; border: 1px solid var(--linea); border-radius: 14px; background: var(--superficie); }
.ds-territorio-indicadores article:first-child { background: var(--acento); border-color: var(--acento); }
.ds-territorio-indicadores article:first-child :is(h2, strong, p) { color: var(--sobre-acento); }
.ds-territorio-indicadores article:first-child p { opacity: .85; }
.ds-territorio-indicadores h2 { margin: 0 0 10px; color: var(--tinta-2); font-size: 12px; font-weight: 500; }
.ds-territorio-indicadores strong { display: block; color: var(--tinta); font-size: clamp(30px, 3vw, 42px); font-weight: 550; line-height: 1.2; letter-spacing: -.03em; font-variant-numeric: tabular-nums; overflow-wrap: anywhere; }
.ds-territorio-indicadores strong small { font-size: 18px; color: var(--tinta-2); font-weight: 400; }
.ds-territorio-indicadores p { margin: 10px 0 0; color: var(--tinta-2); font-size: 11px; line-height: 1.6; }

.ds-territorio-indicadores{font-family:var(--fuente,'Geist Variable',ui-sans-serif,system-ui,-apple-system,'Segoe UI',sans-serif);}@media(max-width:760px){.ds-territorio-indicadores{grid-template-columns:1fr 1fr;gap:12px;margin-bottom:20px;}.ds-territorio-indicadores article{padding:16px;}.ds-territorio-indicadores strong{font-size:26px;}}

.ds-territorio-preview{font-family:var(--fuente,'Geist Variable',ui-sans-serif,system-ui,-apple-system,'Segoe UI',sans-serif);color:var(--tinta);}.ds-territorio-preview button:focus-visible{outline:2px solid var(--acento);outline-offset:3px;}
.ds-territorio-grafico { padding: 22px; border: 1px solid var(--linea); border-radius: 14px; background: var(--superficie); }
.ds-territorio-grafico h2 { margin: 0; font-size: 20px; font-weight: 600; line-height: 1.3; letter-spacing: -.025em; }
.ds-territorio-grafico-cabecera p { margin: 7px 0 18px; font-size: 12px; color: var(--tinta-2); line-height: 1.6; }
.ds-territorio-grafico-leyenda { display: flex; gap: 18px; flex-wrap: wrap; font-size: 11px; color: var(--tinta-2); }
.ds-territorio-grafico-leyenda span { display: inline-flex; align-items: center; gap: 7px; }
.ds-territorio-grafico-leyenda i { width: 14px; height: 7px; border-radius: 2px; background: var(--acento); }
.ds-territorio-grafico-leyenda span + span i { background: var(--dato-tres); }
.ds-territorio-grafico-escala { display: flex; justify-content: space-between; margin: 22px 65px 6px 104px; font-size: 10px; color: var(--tinta-2); font-variant-numeric: tabular-nums; }
.ds-territorio-grafico-filas { display: grid; gap: 6px; }
.ds-territorio-grafico-fila { display: grid; grid-template-columns: 90px minmax(0, 1fr); gap: 14px; align-items: center; padding: 10px 8px; margin: 0 -8px; border: 0; border-radius: 7px; color: var(--tinta); background: transparent; font: inherit; text-align: left; cursor: pointer; min-height: 56px; transition: background-color 140ms ease-out; }
.ds-territorio-grafico-fila:hover, .ds-territorio-grafico-fila[aria-pressed="true"] { background: var(--acento-suave); }
.ds-territorio-grafico-nombre { font-size: 12px; font-weight: 550; line-height: 1.4; overflow-wrap: anywhere; }
.ds-territorio-grafico-par { display: grid; gap: 7px; min-width: 0; }
.ds-territorio-grafico-serie { display: grid; grid-template-columns: minmax(0, 1fr) 57px; gap: 8px; align-items: center; }
.ds-territorio-grafico-serie strong { font-size: 11px; font-weight: 550; text-align: right; font-variant-numeric: tabular-nums; }
.ds-territorio-grafico-carril { height: 8px; border-radius: 3px; background: var(--superficie-2); overflow: hidden; }
.ds-territorio-grafico-carril i { display: block; width: 100%; height: 100%; border-radius: inherit; background: var(--acento); transform-origin: left center; transition: transform 320ms cubic-bezier(.16,1,.3,1); animation: ds-territorio-trazo 360ms cubic-bezier(.16,1,.3,1); }
.ds-serie-referidos .ds-territorio-grafico-carril i { background: var(--dato-tres); }
@keyframes ds-territorio-trazo { from { transform: scaleX(0); } }
.ds-territorio-grafico-nota, .ds-territorio-grafico-vacio { margin: 18px 0 0; font-size: 11px; color: var(--tinta-2); line-height: 1.7; }
.ds-territorio-grafico-vacio { padding: 22px 0; }

@media(max-width:760px){.ds-territorio-grafico{padding:20px;}}@media(prefers-reduced-motion:reduce){.ds-territorio-grafico-carril i,.ds-territorio-grafico-fila{transition:none;animation:none;}}

.ds-territorio-inspector { padding: 24px; min-height: 280px; scroll-margin-top: 80px; }
.ds-territorio-inspector:focus-visible { outline: 2px solid var(--acento); outline-offset: -3px; }
.ds-territorio-inspector-cabecera { display: flex; justify-content: space-between; align-items: start; gap: 12px; }
.ds-territorio-inspector h2 { margin: 0; font-size: 19px; font-weight: 600; line-height: 1.3; letter-spacing: -.02em; overflow-wrap: anywhere; }
.ds-territorio-inspector-cabecera button { display: grid; place-items: center; flex-shrink: 0; width: 28px; height: 28px; border: 0; border-radius: 6px; background: var(--superficie-2); color: var(--tinta-2); cursor: pointer; }
.ds-territorio-inspector-ayuda { margin: 14px 0 0; color: var(--tinta-2); font-size: 12px; line-height: 1.7; }
.ds-territorio-inspector-subtitulo { font-size: 12px; color: var(--tinta-2); margin: 7px 0 22px; }
.ds-territorio-recorrido { display: grid; grid-template-columns: 1fr 18px; gap: 12px; align-items: center; margin: 24px 0; font-size: 12px; }
.ds-territorio-recorrido svg { transform: rotate(90deg); width: 13px; color: var(--tinta-2); }
.ds-territorio-cifras-seleccion { margin: 0; font-size: 12px; }
.ds-territorio-cifras-seleccion > div { display: flex; flex-wrap: wrap; justify-content: space-between; align-items: baseline; gap: 10px; padding: 12px 0; border-bottom: 1px solid var(--linea); }
.ds-territorio-cifras-seleccion dt { color: var(--tinta-2); }
.ds-territorio-cifras-seleccion dd { margin: 0; color: var(--tinta); font-size: 22px; font-weight: 550; font-variant-numeric: tabular-nums; }
.ds-territorio-detalle { display: flex; align-items: center; justify-content: center; gap: 14px; width: 100%; min-height: 40px; margin-top: 20px; }
.ds-territorio-alcance { padding: 20px 24px; border-top: 1px solid var(--linea); }
.ds-territorio-alcance h3 { font-size: 12px; margin: 0 0 10px; font-weight: 600; }
.ds-territorio-alcance p { font-size: 11px; line-height: 1.7; margin: 8px 0 0; color: var(--tinta-2); }
.ds-territorio-comparacion { margin-top: 28px; background: var(--superficie); border: 1px solid var(--linea); border-radius: 14px; overflow: hidden; }
.ds-territorio-ficha-geo { font-size: 11px; line-height: 1.5; margin: 14px 0; }
.ds-territorio-ficha-geo div { display: flex; justify-content: space-between; gap: 12px; padding: 6px 0; }
.ds-territorio-ficha-geo dt { color: var(--tinta-2); }
.ds-territorio-ficha-geo dd { margin: 0; text-align: right; }
.ds-territorio-preview{font-family:var(--fuente,'Geist Variable',ui-sans-serif,system-ui,-apple-system,'Segoe UI',sans-serif);background:var(--superficie);color:var(--tinta);}.ds-territorio-preview button:focus-visible,.ds-territorio-preview input:focus-visible{outline:2px solid var(--acento);outline-offset:3px;}.ds-territorio-inspector-cabecera button:hover{background:var(--superficie-2);color:var(--tinta);}@media(max-width:760px){.ds-territorio-inspector{min-height:0;padding:20px;}.ds-territorio-alcance{padding:18px 20px;}}
.ds-territorio-inspector{padding:22px;min-height:0;border:1px solid var(--linea);border-radius:14px;background:var(--superficie);}.ds-territorio-inspector-cabecera button{width:44px;height:44px;}.ds-territorio-recorrido{display:flex;flex-wrap:wrap;gap:8px;margin:20px 0;}.ds-territorio-recorrido svg{transform:none;width:10px;}@media(max-width:760px){.ds-territorio-inspector{padding:20px;}.ds-territorio-detalle{min-height:44px;}}

.ds-territorio-tabla-cabecera { display: flex; justify-content: space-between; align-items: center; gap: 24px; padding: 24px; }
.ds-territorio-tabla-cabecera h2 { font-size: 20px; font-weight: 600; letter-spacing: -.02em; margin: 0; }
.ds-territorio-tabla-cabecera p { font-size: 12px; color: var(--tinta-2); line-height: 1.6; margin: 6px 0 0; }
.ds-territorio-tabla-cabecera .ds-territorio-buscar { width: 260px; flex-shrink: 0; min-height: 40px; }
.ds-territorio-tabla-filtros { display: flex; flex-wrap: wrap; gap: 12px; justify-content: space-between; align-items: center; padding: 0 24px 16px; }
.ds-territorio-tabla-filtros > div { display: flex; flex-wrap: wrap; gap: 6px; }
.ds-territorio-tabla-filtros button { min-height: 34px; padding: 6px 10px; border: 0; border-radius: 6px; font: inherit; font-size: 11px; background: var(--superficie-2); color: var(--tinta-2); cursor: pointer; }
.ds-territorio-tabla-filtros button[aria-pressed="true"] { background: var(--acento-suave); color: var(--acento); font-weight: 600; }
.ds-territorio-tabla-filtros > span { color: var(--tinta-2); font-size: 11px; }
.ds-territorio-tabla-scroll { max-height: 460px; overflow: auto; scrollbar-width: thin; scrollbar-color: var(--linea-fuerte) transparent; }
.ds-territorio-tabla-scroll:focus-visible { outline: 2px solid var(--acento); outline-offset: -2px; }
.ds-territorio-comparacion table { width: 100%; min-width: 610px; border-spacing: 0; font-size: 13px; }
.ds-territorio-comparacion thead th { position: sticky; top: 0; background: var(--superficie-2); z-index: 1; font-weight: 500; font-size: 11px; color: var(--tinta-2); padding: 0; border-bottom: 1px solid var(--linea); }
.ds-territorio-comparacion thead th > button { display: flex; align-items: center; justify-content: end; gap: 8px; width: 100%; min-height: 46px; padding: 10px 24px; font: inherit; color: inherit; border: 0; background: transparent; cursor: pointer; }
.ds-territorio-comparacion thead th:first-child > button { justify-content: start; }
.ds-territorio-comparacion thead th:last-child { padding: 10px 24px; text-align: right; }
.ds-territorio-comparacion thead svg { width: 14px; height: 14px; flex-shrink: 0; opacity: .5; }
.ds-territorio-comparacion thead th[aria-sort="ascending"], .ds-territorio-comparacion thead th[aria-sort="descending"] { color: var(--acento); }
.ds-territorio-comparacion thead th[aria-sort="ascending"] svg, .ds-territorio-comparacion thead th[aria-sort="descending"] svg { opacity: 1; }
.ds-territorio-comparacion thead th[aria-sort="ascending"] svg { transform: rotate(180deg); }
.ds-territorio-columna-corta { display: none; }
.ds-territorio-comparacion tbody th, .ds-territorio-comparacion td { border-bottom: 1px solid var(--linea); padding: 12px 24px; text-align: right; font-weight: 500; font-variant-numeric: tabular-nums; }
.ds-territorio-comparacion tbody th { padding: 0; width: 38%; text-align: left; }
.ds-territorio-comparacion tbody tr:hover { background: var(--superficie-2); }
.ds-territorio-comparacion tbody tr.ds-seleccionada { background: var(--acento-suave); }
.ds-territorio-tabla-nombre { display: flex; align-items: center; gap: 12px; width: 100%; min-height: 62px; padding: 12px 24px; border: 0; background: transparent; color: var(--tinta); font: inherit; font-size: 13px; text-align: left; cursor: pointer; }
.ds-territorio-tabla-nombre small { display: block; color: var(--tinta-2); margin-top: 3px; font-size: 10px; font-weight: 400; }
.ds-territorio-tabla-abrir { display: inline-flex; align-items: center; justify-content: end; gap: 8px; min-height: 36px; border: 0; padding: 6px 0 6px 8px; background: transparent; color: var(--acento); font: inherit; font-size: 11px; cursor: pointer; }
.ds-territorio-tabla-abrir svg { width: 13px; height: 13px; }
.ds-territorio-comparacion td.ds-cifra-protegida { color: var(--tinta-2); font-size: 11px; font-weight: 400; }
.ds-territorio-comparacion td.ds-territorio-tabla-vacio { padding: 32px 24px; text-align: center; color: var(--tinta-2); font-size: 12px; }
.ds-territorio-tabla-vacio button { display: block; margin: 12px auto 0; border: 0; background: transparent; color: var(--acento); font: inherit; cursor: pointer; text-decoration: underline; text-underline-offset: 3px; min-height: 36px; }
.ds-territorio-tabla-nota { font-size: 11px; line-height: 1.7; color: var(--tinta-2); margin: 0; padding: 16px 24px; }
.ds-territorio-lista-cabecera h2 { font-size: 13px; font-weight: 600; margin: 0 0 12px; }
.ds-territorio-buscar { display: flex; align-items: center; gap: 8px; border: 1px solid var(--linea); border-radius: 6px; padding: 8px 10px; color: var(--tinta-2); }
.ds-territorio-buscar input { width: 100%; min-width: 0; background: transparent; color: var(--tinta); border: 0; font: inherit; font-size: 12px; outline: none; }
.ds-territorio-buscar:focus-within { outline: 2px solid var(--acento); outline-offset: 2px; }
.ds-territorio-preview{font-family:var(--fuente,'Geist Variable',ui-sans-serif,system-ui,-apple-system,'Segoe UI',sans-serif);color:var(--tinta);}.ds-territorio-comparacion{margin-top:0;border:1px solid var(--linea);border-radius:14px;background:var(--superficie);overflow:hidden;}.ds-territorio-punto{width:7px;height:7px;border-radius:2px;flex-shrink:0;}.ds-dato-uno{background:var(--dato-uno,#b5d1c0);}.ds-dato-cero{background:var(--dato-cero,#e0e7e2);}.ds-dato-protegido{background:repeating-linear-gradient(135deg,#dae0db 0px,#dae0db 3px,#8c998e 3px,#8c998e 4px);}.ds-territorio-preview button:focus-visible,.ds-territorio-preview input:focus-visible{outline:2px solid var(--acento);outline-offset:3px;}.ds-territorio-tabla-filtros button:hover{background:var(--superficie-2);color:var(--tinta);}.ds-territorio-tabla-abrir:hover{text-decoration:underline;}.ds-territorio-comparacion thead button:hover{color:var(--acento);}
@media(max-width:760px){  .ds-territorio-tabla-cabecera { flex-direction: column; align-items: stretch; padding: 20px 16px 16px; gap: 16px; }
  .ds-territorio-tabla-cabecera .ds-territorio-buscar { width: 100%; }
  .ds-territorio-tabla-filtros { padding: 0 16px 14px; }
  .ds-territorio-comparacion table { min-width: 0; table-layout: fixed; }
  .ds-territorio-comparacion thead th:first-child, .ds-territorio-comparacion tbody th { width: 46%; }
  .ds-territorio-comparacion thead th:last-child, .ds-territorio-comparacion tbody td:last-child:not([colspan]) { display: none; }
  .ds-territorio-columna-completa { display: none; }
  .ds-territorio-columna-corta { display: inline; }
  .ds-territorio-comparacion thead th > button, .ds-territorio-comparacion tbody td { padding: 10px; }
  .ds-territorio-comparacion thead th > button { gap: 3px; font-size: 10px; }
  .ds-territorio-comparacion thead svg { width: 11px; }
  .ds-territorio-tabla-nombre { padding: 12px; font-size: 12px; gap: 8px; overflow-wrap: anywhere; }
  .ds-territorio-tabla-nota { padding: 16px; }
}
@media(max-width:760px){.ds-territorio-tabla-filtros button{min-height:44px;}}
